package dev.sgs.validation.client.art;

import dev.sgs.core.Kingdom;

/** Generated by tools/faction_art_direction.py from art/direction/faction-tokens.json. */
public record FactionStyle(int main,int trim,int ink) {
    public static FactionStyle of(int ordinal){
        if(ordinal<0 || ordinal>=Kingdom.values().length)return new FactionStyle(0xff544332,0xffb39561,0xff5b4732);
        return switch(Kingdom.values()[ordinal]){
            case SHU->new FactionStyle(0xffa53632,0xffc9a976,0xff722e2b);
            case WEI->new FactionStyle(0xff315c91,0xffc2cdd3,0xff203c60);
            case WU->new FactionStyle(0xff2d7759,0xffb9a879,0xff24523f);
            case QUN->new FactionStyle(0xffb69a58,0xffd8d8ce,0xff756642);
        };
    }
}
